def m2_track_support_union(track):
    return set().union(*(segment["support_ids"] for segment in track["segments"]))


def m2_track_passes_final_filters(track):
    """
    This is NOT keep-top-2: every track either passes or fails fixed criteria.
    """
    points_by_frame = m2_track_points_by_frame(track)
    support_count = len(m2_track_support_union(track))
    coverage = len(points_by_frame) / m2_num_frames

    passes = (
        coverage >= m2_min_final_coverage
        and support_count >= m2_min_final_support
        and len(track["segments"]) >= m2_min_final_segments
    )

    return passes, {
        "coverage": coverage,
        "support_count": support_count,
        "num_segments": len(track["segments"]),
        "num_frames": len(points_by_frame),
    }

def m2_ground_truth_by_label(label):
    if label == 1:
        track = m2_gt1_clean
    elif label == 2:
        track = m2_gt2_clean
    else:
        raise ValueError("label must be 1 or 2.")

    return {
        int(frame): np.array([x, y])
        for x, y, frame, _ in track
    }

def m2_evaluate_track_against_gt(track):
    """
    Evaluation only. Ground-truth labels are NOT used by the algorithm.
    """
    support_ids = m2_track_support_union(track)
    rows = m2_rows_for_support_ids(support_ids)
    labels = np.array([int(label) for label in rows[:, m2_label_col]])

    positive_labels = labels[labels > 0]
    if len(positive_labels) == 0:
        matched_label = 0
    else:
        counts = np.bincount(positive_labels, minlength=3)
        matched_label = int(np.argmax(counts))

    label_counts = {
        0: int(np.sum(labels == 0)),
        1: int(np.sum(labels == 1)),
        2: int(np.sum(labels == 2)),
    }

    if matched_label == 0:
        return {
            "matched_label": 0,
            "label_counts": label_counts,
            "mean_deviation": np.inf,
            "max_deviation": np.inf,
            "num_eval_frames": 0,
        }

    gt_positions = m2_ground_truth_by_label(matched_label)
    track_points = m2_track_points_by_frame(track)

    deviations = []
    for frame, position in track_points.items():
        if frame in gt_positions:
            deviations.append(float(np.linalg.norm(position - gt_positions[frame])))

    return {
        "matched_label": matched_label,
        "label_counts": label_counts,
        "mean_deviation": float(np.mean(deviations)) if deviations else np.inf,
        "max_deviation": float(np.max(deviations)) if deviations else np.inf,
        "num_eval_frames": len(deviations),
    }

